from h import *
R(9931828,"كرات الشوكولاتة والقرع بالطاقة",
"كرات القرع هذه دافئة ولذيذة وهي الحلوى المثالية للخريف.",
"18 كرة","حصة واحدة",
["¼ كوب زبدة اللوز","¼ كوب شراب القيقب","¼ كوب هريس القرع (وليس حشوة فطيرة القرع)","100 غرام دقيق اللوز (حوالي 1 كوب)","2 ملعقة كبيرة مسحوق كاكاو خام غير محلى","2 ملعقة صغيرة قرفة"],
["ضع زبدة اللوز وشراب القيقب وهريس القرع في وعاء خلط متوسط. حرّك جيدًا بشوكة حتى تمتزج.",
"ثم أضف دقيق اللوز ومسحوق الكاكاو والقرفة وحرّك حتى تمتزج.",
"استخدم مغرفة كوكيز صغيرة لتقسيم الخليط وشكّله على هيئة كرات. ثم ضعها في الثلاجة لمدة 15 دقيقة أو أكثر لتتماسك.",
"اختياري: في وعاء صغير، اخلط 1 ملعقة كبيرة من سكر جوز الهند و1 ملعقة صغيرة من القرفة لتقليب بعض الكرات أو كلها في الخليط. ملاحظة: سيؤدي ذلك إلى زيادة السكر."],
["سيكون الخليط لزجًا، لذا استخدم يدين رطبتين لتشكيل الكرات كي لا يلتصق بهما.","ستكون الكرات المشكّلة طرية، لذا ضعها في الثلاجة لمدة 15 دقيقة على الأقل قبل تناولها لتتماسك.","يُحفظ المتبقي في الثلاجة لمدة 3-4 أيام أو في المجمّد لمدة تصل إلى 3 أشهر."],
{})
R(9936271,"شيبس الفاصولياء السوداء المنزلي",
"إليك نسخة صحية من رقائق البطاطس المفضلة لديك. رقائق الفاصولياء السوداء هذه غنية بالبروتين وخالية تمامًا من الشعور بالذنب.",
"3 حصص","حصة واحدة",
["½ كوب دقيق الفاصولياء السوداء (أطحن الفاصولياء السوداء في خلاط فيتامكس)","1 ملعقة كبيرة زيت الأفوكادو أو زيت طهي آخر، لا تستخدم زيت الزيتون (انظر الملاحظات أدناه للحصول على خيار دون زيت)","½-⅔ كوب ماء","½-1 ملعقة صغيرة ملح البحر حسب الرغبة"],
["سخّن الفرن مسبقًا على 350 درجة فهرنهايت (175° مئوية) وبطّن صينيتي خبز بورق الزبدة.",
"إذا لم يكن لديك دقيق الفاصولياء السوداء، فيمكنك تحضيره في خلاط قوي مثل فيتامكس. قِس نصف كوب من الفاصولياء السوداء الجافة وشغّل الخلاط على أعلى سرعة حتى تحصل على قوام يشبه الدقيق. سيستغرق ذلك حوالي 15-20 ثانية.",
"اخلط الملح ودقيق الفاصولياء في وعاء متوسط. ثم أضف الزيت وامزج جيدًا. استخدم شوكة لدمج الزيت جيدًا. ثم اسكب الماء ببطء، مع البدء بنصف كوب، وأضف المزيد عند الحاجة للوصول إلى عجينة سائلة قليلًا.",
"اسكب ملاعق صغيرة من العجينة على صينية الخبز، مع ترك مساحة كبيرة بين كل واحدة. يجب أن تنتشر الرقائق قليلًا. ثم، باستخدام شوكة، اضغط على كل رقاقة وافردها برفق لتصبح العجينة رقيقة جدًا للحصول على أقصى قرمشة.",
"اخبزها لمدة 10 دقائق، ثم باستخدام شوكة اقلب الرقائق واخبزها 8-10 دقائق إضافية، مع المراقبة عن كثب كي لا تحترق. **انظر الملاحظة 3",
"أخرجها من الفرن واترك الرقائق تبرد تمامًا قبل لمسها. تتناسب هذه الرقائق بشكل خاص مع الجواكامولي المنزلي، أو يمكنك تناولها كما هي."],
["لا تقلق إذا كان في دقيق الفاصولياء السوداء بعض البقع الأسمك. سترى بعض البقع السوداء هنا وهناك من قشر الفاصولياء. وعند وضع العجينة على صينية الخبز، لا تهتم بحجم الرقائق وشكلها. فلا يلزم أن تكون متماثلة، وما دامت رقيقة فستتقرمش. ومع ذلك، احرص على ألا تترك ثقوبًا عند فرد الرقائق وإلا قد تتكسر عند قلبها. استخدم شوكة كبيرة لقلب الرقائق، وبدلًا من رفعها عن ورق الزبدة، مرّر الشوكة أو ادفعها تحت كل رقاقة للتأكد من أنها لا تلتصق بالورق، ثم اقلبها. ودفع الشوكة تحت كل رقاقة سيمنحها أيضًا التموجات كما في الصورة. وللحصول على وصفة دون زيت، تجاوز الزيت وتوخَّ عناية إضافية عند قلب الرقائق. فقد تلتصق قليلًا بورق الزبدة أثناء الخبز، لذا اكشط/مرّر برفق الجزء السفلي من كل رقاقة بشوكة كبيرة لقلبها. ولعمل رقائق بنكهات مختلفة، يمكنك أيضًا إضافة رشة من مسحوق الثوم أو الكمون أو فلفل الكايين أو البابريكا إلى وعاء المكونات الجافة، قبل خلط الزيت أو الماء. يكون طعم هذه الرقائق أفضل في اليوم نفسه الذي تُحضَّر فيه، إذ قد تفقد قرمشتها، لذا خطّط لتناولها فورًا. أبقِها في طبقة واحدة حتى حين التقديم كي لا تصبح طرية بسبب تكديسها فوق بعضها."],
{})
R(9938812,"سلطة المعكرونة بالشمندر",
"سلطة المعكرونة بالشمندر النابضة بالألوان هذه تجمع بين الشمندر الطري والمعكرونة «ألدنتي»، مقلّبة في صلصة فينيغريت لاذعة.",
"4 حصص","حصة واحدة",
["½ رطل معكرونة روتيني أو معكرونة من اختيارك","علبة شمندر 13.5 أونصة مقطع إلى مكعبات","2 كوب خيار مقطوع إلى أرباع طولًا ومقطع إلى شرائح","½ كوب بيكان أو جوز مفروم","¼ كوب بصل أحمر مقطع إلى مكعبات","2 ملعقة كبيرة عصير ليمون (حوالي نصف ليمونة كبيرة)","2 ملعقة كبيرة خل التفاح","1 ملعقة كبيرة شراب القيقب","1 ملعقة صغيرة شبت","½ ملعقة صغيرة مسحوق الثوم","ملح وفلفل حسب الرغبة","ثوم معمر (شيف) أو بقدونس أو ريحان طازج مفروم ناعمًا"],
["اترك قدرًا كبيرًا من الماء المملح بوفرة حتى يغلي واطبخ المعكرونة وفق تعليمات العبوة للحصول على معكرونة «ألدنتي». صفِّها فورًا واشطفها لمنع الإفراط في نضجها. ثم انقلها إلى وعاء كبير.",
"أثناء طبخ المعكرونة، اخلط جميع مكونات صلصة السلطة في وعاء صغير وامزج جيدًا.",
"ثم أضف جميع مكونات السلطة المتبقية إلى الوعاء مع المعكرونة المطبوخة واسكب الصلصة فوقها. امزج جيدًا، وزيّنها بالثوم المعمر الطازج وضعها في الثلاجة لمدة ساعة أو أكثر، أو استمتع بها فورًا."],
["أضف الملح إلى ماء سلق المعكرونة. احرص على إضافة كمية كافية من الملح إلى قدر الماء للحصول على أفضل قوام ونكهة. إليك دليلًا مفيدًا لمساعدتك على تمليح الماء بشكل مثالي في كل مرة.","اطبخ المعكرونة «ألدنتي». لا تفرط في طبخها! «ألدنتي» تعني أن المعكرونة تبقى متماسكة بعد الطبخ، مما يعطي قوامًا مثاليًا في كل لقمة. ولضمان عدم الإفراط في نضجها، ابدأ بتذوقها قبل بضع دقائق من الموعد المذكور على العبوة. يجب أن تكون طرية لكن متماسكة.","يُحفظ المتبقي في الثلاجة لمدة 3-4 أيام."],
{"For the dressing":"للصلصة","For garnish":"للتزيين"})
R(9939692,"سموذي التفاح الحامض",
"سموذي التفاح الحامض هذا يقدّم لمسة جميلة على نكهات السموذي المعتادة. حلو وحامض، منعش تمامًا، ومليء بالعناصر الغذائية!",
"حصة واحدة","حصة واحدة",
["1 حبة تفاح غراني سميث منزوعة القلب","½ ليمونة معصورة","⅓ كوب خيار (حوالي شريحة/قطعة بطول 3 بوصات)","1 حفنة أوراق سبانخ صغيرة (بيبي)","1 كوب مكعبات ثلج"],
["ضع جميع المكونات في الخلاط وشغّله حتى يصبح ناعمًا. استمتع به فورًا."],
[],
{})
R(9940851,"قرنبيط مشوي نباتي بالثوم والبارميزان",
"هذا القرنبيط المشوي النباتي بالثوم والبارميزان سهل التحضير جدًا ولذيذ بشكل لا يُصدَّق! 6 مكونات فقط!",
"4 حصص","حصة واحدة",
["6 أكواب زهيرات قرنبيط (حوالي رأس قرنبيط صغير واحد أو نصف رأس كبير)","2 فص ثوم مفروم","1.5 ملعقة كبيرة خل بلسمي","1 ملعقة كبيرة عصير ليمون","¼ ملعقة صغيرة ملح البحر","3 ملاعق كبيرة جبن بارميزان نباتي","بقدونس طازج للتقديم","صلصة رانش نباتية للتغميس"],
["سخّن الفرن مسبقًا على 425° فهرنهايت (220° مئوية) بوضع الشوي بالحمل الحراري وبطّن صينية خبز بورق الزبدة.",
"استخدم سكينًا حادة لتقطيع القرنبيط إلى زهيرات صغيرة بحجم لقمة وضعها في وعاء كبير.",
"في وعاء صغير، اخلط الثوم والخل وعصير الليمون والملح. ثم اسكب الخليط على القرنبيط وامزج جيدًا لتتغلف القطع بالتساوي.",
"رتّب القرنبيط على الصينية المجهزة في طبقة واحدة مع ترك مساحة كبيرة بين كل قطعة. اشوِه لمدة 10 دقائق ثم أخرجه من الفرن وانثر عليه جبن البارميزان النباتي. ثم أعده إلى الفرن لمدة 6-8 دقائق إضافية، حتى يصبح بنيًا ذهبيًا."],
["قطّع زهيرات القرنبيط إلى قطع متساوية الحجم (قدر المستطاع) لينضج بالتساوي. احرص على ترتيب القرنبيط في طبقة واحدة مع ترك مساحة كبيرة بين كل قطعة. فهذا سيسرّع وقت الطهي ويعطي حوافًا أكثر قرمشة. وإذا لم يكن لديك فرن بالحمل الحراري، فاتبع التعليمات نفسها، لكن قد تحتاج إلى إضافة بضع دقائق من وقت الشوي. يكون طعم هذا القرنبيط المشوي النباتي أفضل وهو طازج، لكن المتبقي يُحفظ في الثلاجة لمدة 3-4 أيام."],
{"Optional":"اختياري"})
R(9942188,"جزر وهليون مشويان",
"طبق جانبي بسيط من الجزر والهليون المشويين يتناسب مع أي وجبة.",
"6 حصص","حصة واحدة",
["1 رطل ساق هليون (حوالي حزمة واحدة)","1 رطل جزر (حوالي 6-8 حبات جزر متوسطة)","1 ملعقة كبيرة عصير ليمون","1 ملعقة صغيرة مسحوق الثوم","1 ملعقة صغيرة بذور السمسم","½ ملعقة صغيرة ملح البحر أو حسب الرغبة"],
["سخّن الفرن مسبقًا على 400° فهرنهايت (205° مئوية) وبطّن صينية خبز كبيرة بورق الزبدة. (أو استخدم صينيتين إن لم تكن لديك صينية كبيرة جدًا.)",
"اقطع نهايات الهليون، وقشّر الجزر. ثم قطّع الجزر إلى أرباع طولًا إن كان متوسط السماكة. وإذا كان الجزر سميكًا جدًا، فقطّعه ليصبح بنحو سماكة الهليون نفسها لينضج بالتساوي.",
"رتّب الخضار على صينية الخبز في طبقة واحدة. ثم رش عليها عصير الليمون وانثر التوابل.",
"اخبزها لمدة 20 دقيقة، ثم اقلبها. ثم واصل الخبز لمدة 5-10 دقائق أخرى أو حتى تصل إلى درجة النضج المرغوبة. (يختلف وقت الخبز حسب سماكة الخضار.)"],
["قطّع الجزر إلى شرائح رقيقة جدًا (بنحو سماكة الهليون نفسها) لينضج بالتساوي.","وإذا كان الجزر أسمك بكثير من الهليون، وكنت تجد صعوبة في تقطيعه رقيقًا بما يكفي، فاترك الجزر يُخبز لمدة 10-15 دقيقة قبل إضافة الهليون."],
{})
R(9950861,"حمص الشمندر الجميل",
"حمص الشمندر الجميل هذا مقبلات مثالية مع الخضار والبسكويت المالح أو إضافة رائعة للبرغر! لونه النابض بالحياة ونكهته اللذيذة لا مثيل لهما!",
"6 حصص (تُنتج حوالي 2 كوب)","حصة واحدة",
["2 حبة شمندر صغيرة مقشرة ومقطعة إلى أرباع","علبة حمص 15 أونصة مصفاة ومغسولة","2 فص ثوم مقشر","2 ملعقة كبيرة خل بلسمي","2 ملعقة كبيرة بذور السمسم","2 ملعقة كبيرة عصير ليمون","¼ كوب ماء، إضافة إلى 1-2 ملعقة كبيرة أخرى إذا لزم للحصول على قوام أخف","½ ملعقة صغيرة ملح البحر"],
["ضع الشمندر في قدر صغير مغطى بالماء واتركه حتى يغلي، واطبخه حتى يصبح سهل الاختراق بالشوكة، حوالي 20 دقيقة.",
"ضع الشمندر وجميع المكونات المتبقية في محضّرة الطعام، وشغّلها حتى تمتزج، مع التوقف لكشط الجوانب عند الحاجة.",
"قدّمه مع خبز البيتا أو الخضار أو البسكويت المالح، واستمتع به!"],
["تُنتج الوصفة حوالي 2 كوب. احفظ المتبقي في وعاء محكم الإغلاق في الثلاجة لمدة تصل إلى 5 أيام."],
{})
R(9952260,"بيكان بنكهة البيكون المسكّر",
"بيكان بنكهة البيكون المسكّر، المقرمش والمدخن والمالح/الحلو، أو ما يُعرف بقطع البيكون النباتي، شهي يسيل له اللعاب ويسبب الإدمان بشكل لا يُصدَّق! سترغب في رش هذه القطع المقرمشة على كل شيء!",
"8 حصص","حصة واحدة",
["1 كوب أنصاف البيكان","3 ملاعق كبيرة تاماري أو صلصة صويا إن لم تكن تتجنب الغلوتين","¼ كوب سكر جوز الهند أو سكر بني","2 ملعقة صغيرة بابريكا مدخنة","⅛ ملعقة صغيرة فلفل أسود (اختياري لكن يُنصح به)"],
["افرد ورقة من ورق الزبدة على صينية أو سطح المطبخ.",
"ثم ضع البيكان في محضّرة الطعام وشغّلها بنبضات قصيرة 7-8 مرات لتفتيته. لا يلزم أن تكون القطع متساوية الحجم، واحرص على عدم الإفراط في المعالجة. فأنت تريد قطعًا خشنة وليس فتاتًا. اتركه جانبًا.",
"الآن ضع كل شيء، ما عدا البيكان، في مقلاة صغيرة واطبخه على نار متوسطة مع التحريك المتكرر لمدة 2-3 دقائق. يجب أن يكون الخليط فوارًا، ثم أضف قطع البيكان. امزج جيدًا واطبخ 2-3 دقائق أخرى حتى يتغلف البيكان بالتساوي.",
"ارفعه عن النار وافرده على ورق الزبدة. اتركه يبرد، ثم فتّته واحفظه في وعاء أو برطمان.",
"بان كيك مالح","بطاطس مشوية، هريس البطاطس، بولتين، بطاطس منزلية مقلية (كل أنواع البطاطس!)","سلطة كوب"],
["احرص على عدم الإفراط في معالجة البيكان. فقط شغّل المحضّرة بنبضات قصيرة حتى يتفتت وتفقّدها كثيرًا. فأنت لا تريد فتاتًا! حضّر قطع البيكون النباتي مسبقًا ليتاح لها وقت للتبريد قبل تناولها. فالدفعة الواحدة لا تدوم طويلًا، لذا إذا أردت تحضير بعضها للتجميد، فضاعف الوصفة! 😉 احفظ المتبقي في برطمان أو وعاء محكم الإغلاق في درجة حرارة الغرفة لمدة تصل إلى أسبوع، أو في الثلاجة لمدة 2-3 أسابيع. جمّده في وعاء محكم الإغلاق لمدة شهرين. الوصفة مستوحاة من Fifteen Spatulas"],
{"Ideas for using your candied bacon pecans (optional)":"أفكار لاستخدام البيكان بنكهة البيكون المسكّر (اختياري)"})
save('/mnt/c/WSL/davita/translations/out_tar3_part10.json')
